from itertools import combinations
from fractions import Fraction as F
P={"A":(F(0),F(4)),"B":(F(-4),F(0)),"C":(F(4),F(0)),"D":(F(0),F(0)),"E":(F(0),F(2))}
lines=[["A","B"],["A","C"],["B","D","C"],["A","E","D"],["B","E"],["C","E"]]
def onseg(p,q):
    return any(p in l and q in l for l in lines)
def col(a,b,c):
    (x1,y1),(x2,y2),(x3,y3)=P[a],P[b],P[c]
    return (x2-x1)*(y3-y1)-(y2-y1)*(x3-x1)==0
n=sum(1 for a,b,c in combinations(P,3) if not col(a,b,c) and onseg(a,b) and onseg(b,c) and onseg(a,c))
opts={"A":8,"B":9,"C":11,"D":10}
assert n==opts["A"]
for k in "BCD": assert n!=opts[k]

syn={"simple":{"basic","easy","plain"},"difficult":{"complex","hard","tough"}}
assert "basic" in syn["simple"]
opts={"A":"trivial","B":"imaginary","C":"complex","D":"wrong"}
fits=[k for k,v in opts.items() if v in syn["difficult"]]
assert fits==["C"]

pat="Y_Y__Y_T_Y_Y"
opts={"A":"TYTYTY","B":"YTYTYT","C":"TTYYTT","D":"TYTYYT"}
def fill(o):
    it=iter(o); return "".join(next(it) if c=="_" else c for c in pat)
def periodic(s):
    return any(len(s)%p==0 and s==s[:p]*(len(s)//p) for p in range(2,len(s)//2+1))
fits=[k for k,v in opts.items() if periodic(fill(v))]
assert fits==["D"]

opts={"A":"SUZY","B":"MPUT","C":"PRWV","D":"QSXW"}
g={k:tuple(ord(b)-ord(a) for a,b in zip(v,v[1:])) for k,v in opts.items()}
from collections import Counter
c=Counter(g.values())
odd=[k for k,v in g.items() if c[v]==1]
assert odd==["B"]

